package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.Aspect;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class RunicAudit {
 static int ticks,page;static volatile boolean ready,damagePassed,augmentPassed;static ItemStack wand;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_RUNIC FAIL "+s);System.out.println("TC4_RUNIC PASS "+s);}
 static void clear(ServerPlayer p){for(int i=0;i<4;i++)BaublesInventory.of(p).setItem(i,ItemStack.EMPTY);for(var slot:net.minecraft.world.entity.EquipmentSlot.values())if(slot.getType()==net.minecraft.world.entity.EquipmentSlot.Type.HUMANOID_ARMOR)p.setItemSlot(slot,ItemStack.EMPTY);p.getPersistentData().putInt("TC4RunicCharge",0);p.getPersistentData().remove("TC4RunicInfo");RunicRingShield.dirty=true;RunicRingShield.rechargeDelay=0;RunicRingShield.clocks.remove(p.getUUID());p.invulnerableTime=0;p.setHealth(20);p.removeAllEffects();}
 static void equip(ServerPlayer p,RunicAccessories.Kind... kinds){clear(p);for(var k:kinds){int slot=k.slot==baubles.api.BaubleType.AMULET?0:k.slot==baubles.api.BaubleType.BELT?3:BaublesInventory.of(p).getItem(1).isEmpty()?1:2;BaublesInventory.of(p).setItem(slot,new ItemStack(k.item()));}RunicRingShield.clocks.computeIfAbsent(p.getUUID(),id->new long[5])[0]=Long.MAX_VALUE;}
 static void hit(ServerPlayer p,float amount){p.invulnerableTime=0;p.hurt(p.damageSources().generic(),amount);}
 static void prepare(ServerPlayer p){p.setGameMode(GameType.SURVIVAL);p.getAbilities().flying=false;p.onUpdateAbilities();p.getInventory().clearContent();p.removeAllEffects();for(var cat:thaumcraft.api.research.ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new HashSet<>());ThaumometerItem.sync(p,"");p.connection.teleport(40.5,121,35,0,15);p.getFoodData().setFoodLevel(20);
  for(var r:InfusionItemRecipes.all())if(r.key().startsWith("Runic")){var parts=r.componentStacks();check(InfusionItemRecipes.match(parts,new ItemStack(r.central().get()),Set.of(r.research()))==r,"exact infusion ingredients "+r.key());check(InfusionItemRecipes.match(parts,new ItemStack(r.central().get()),Set.of())==null,"research gate "+r.key());if(r.key().equals("RunicRingCharged")){var wrong=new ArrayList<>(parts);wrong.set(3,new ItemStack(Items.POTION));check(InfusionItemRecipes.match(wrong,new ItemStack(r.central().get()),Set.of(r.research()))==null,"wrong potion rejected");}}
  equip(p,RunicAccessories.Kind.RING,RunicAccessories.Kind.RING,RunicAccessories.Kind.AMULET,RunicAccessories.Kind.GIRDLE);check(RunicRingShield.info(p)[0]==28,"two rings amulet and belt original28capacity");var hardened=BaublesInventory.of(p).getItem(1);var tag=NoteData.tag(hardened);tag.putByte("RS.HARDEN",(byte)2);hardened.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(tag));check(RunicRingShield.info(p)[0]==30,"hardened runic NBT adds capacity");check(p.getPersistentData().getInt("TC4RunicCharge")==0,"equipping grants no free charge");
  for(int n=0;n<5;n++){var input=new ItemStack(TC4Modern.ROBE_CHEST.get());var data=NoteData.tag(input);data.putByte("RS.HARDEN",(byte)n);input.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));check(RunicAugmentation.matches(RunicAugmentation.components(input),input,Set.of("RUNICAUGMENTATION"))&&RunicAugmentation.cost(input).getAmount(Aspect.ENERGY)==32*(1<<n)&&RunicAccessories.charge(RunicAugmentation.output(input))==n+1,"dynamic augmentation components cost and preserved output level"+n);}
  wand=WandParts.make(WandParts.CAPS.get("gold"),WandParts.RODDEFS.get("greatwood"));for(var a:Aspect.getPrimalAspects())WandData.add(wand,a,50,true);p.getInventory().setItem(0,wand);RunicRingShield.clocks.get(p.getUUID())[0]=0;ready=true;
 }
 static void damage(ServerPlayer p){check(p.getPersistentData().getInt("TC4RunicCharge")==1,"natural inventory vis recharge grants one charge");check(WandData.get(wand,Aspect.AIR)==4950&&WandData.get(wand,Aspect.EARTH)==4950,"natural recharge costs .5air .5earth");
  equip(p,RunicAccessories.Kind.RING);p.getPersistentData().putInt("TC4RunicCharge",5);hit(p,2.5f);check(p.getHealth()==20&&p.getPersistentData().getInt("TC4RunicCharge")==2,"fractional damage absorbed with original integer truncation");hit(p,5);check(p.getHealth()==17&&p.getPersistentData().getInt("TC4RunicCharge")==0&&RunicRingShield.rechargeDelay==80,"shield exhaustion passes excess damage and delays80ticks");
  equip(p,RunicAccessories.Kind.HEALING);p.getPersistentData().putInt("TC4RunicCharge",4);hit(p,4);var regen=p.getEffect(net.minecraft.world.effect.MobEffects.REGENERATION);check(regen!=null&&regen.getDuration()==240&&regen.getAmplifier()==1,"healing ring grants regenerationII240ticks");p.removeAllEffects();p.getPersistentData().putInt("TC4RunicCharge",4);hit(p,4);check(!p.hasEffect(net.minecraft.world.effect.MobEffects.REGENERATION),"healing ring original20second cooldown");
  equip(p,RunicAccessories.Kind.EMERGENCY,RunicAccessories.Kind.RING);p.getPersistentData().putInt("TC4RunicCharge",1);hit(p,1);check(p.getPersistentData().getInt("TC4RunicCharge")==8,"emergency amulet restores8charge");p.getPersistentData().putInt("TC4RunicCharge",1);hit(p,1);check(p.getPersistentData().getInt("TC4RunicCharge")==0,"emergency60second cooldown");
  equip(p,RunicAccessories.Kind.CHARGED,RunicAccessories.Kind.CHARGED);check(RunicRingShield.info(p)[0]==8&&RunicRingShield.info(p)[1]==2,"two charged rings reduce original interval to1000ms");
  equip(p,RunicAccessories.Kind.KINETIC);var cow=net.minecraft.world.entity.EntityType.COW.create(p.serverLevel());cow.setPos(p.getX()+1,p.getY(),p.getZ());p.serverLevel().addFreshEntity(cow);float before=cow.getHealth();var block=p.blockPosition().below();var state=p.level().getBlockState(block);p.getPersistentData().putInt("TC4RunicCharge",1);hit(p,1);check(cow.getHealth()<before&&p.level().getBlockState(block).equals(state),"kinetic blast damages nearby mob without breaking blocks");cow.discard();
  equip(p,RunicAccessories.Kind.RING);p.getPersistentData().putInt("TC4RunicCharge",5);p.invulnerableTime=0;p.hurt(p.damageSources().drown(),2);check(p.getHealth()==18&&p.getPersistentData().getInt("TC4RunicCharge")==5,"original drowning bypasses shield");p.setHealth(20);damagePassed=true;
  startAugment(p);
 }
 static void startAugment(ServerPlayer p){InfusionAudit.prepare(p);var matrix=InfusionAudit.matrix;matrix.logic.crafting=false;var central=new ItemStack(TC4Modern.ROBE_CHEST.get());var l=p.serverLevel();((InfusionContent.PedestalEntity)l.getBlockEntity(InfusionAudit.POS.below(2))).setItem(central);var parts=RunicAugmentation.components(central);for(int i=0;i<InfusionAudit.components.size();i++)((InfusionContent.PedestalEntity)l.getBlockEntity(InfusionAudit.components.get(i))).setItem(i<parts.size()?parts.get(i):ItemStack.EMPTY);for(int dx:new int[]{-1,1})l.setBlock(InfusionAudit.POS.offset(dx,-2,-4),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);var aspects=RunicAugmentation.cost(central);int i=0;for(var a:aspects.getAspects()){var pos=InfusionAudit.POS.offset(i++*2-2,-2,-4);l.setBlock(pos,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(pos);jar.state.aspect=a;jar.state.amount=aspects.getAmount(a);jar.changed();}InfusionAudit.click(p,p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow());check(matrix.logic.crafting&&matrix.logic.recipeEssentia.visSize()==64,"actual wand starts dynamic robe augmentation");}
 static void finishAugment(ServerPlayer p){var matrix=InfusionAudit.matrix;var l=p.serverLevel();var out=((InfusionContent.PedestalEntity)l.getBlockEntity(InfusionAudit.POS.below(2))).item();System.out.println("TC4_RUNIC altar status crafting="+matrix.logic.crafting+" essentia="+matrix.logic.recipeEssentia.visSize()+" ingredients="+matrix.logic.recipeIngredients.size()+" output="+out+" charge="+RunicAccessories.charge(out));check(!matrix.logic.crafting&&out.is(TC4Modern.ROBE_CHEST.get())&&RunicAccessories.charge(out)==1,"natural altar finishes preserved robe with +1shield");for(var pos:InfusionAudit.components)check(((InfusionContent.PedestalEntity)l.getBlockEntity(pos)).item().isEmpty(),"augmentation components consumed");for(int i=0;i<3;i++)check(((WardedJarEntity)l.getBlockEntity(InfusionAudit.POS.offset(i*2-2,-2,-4))).state.amount==0,"augmentation exact essentia consumed"+i);augmentPassed=true;}
 static final String[] KEYS={"RUNICARMOR","RUNICCHARGED","RUNICHEALING","RUNICKINETIC","RUNICEMERGENCY"};
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.runicAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==95){check(ready,"server setup complete");server.execute(()->damage(server.getPlayerList().getPlayer(id)));}if(ticks==99)mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_BACK);if(ticks==100){check(damagePassed,"damage mechanics complete");check(RunicShieldClient.received>0,"original shield hemisphere packet arrives");LiquidDeathAudit.shot(mc,"runic-shield-world.png");}if(ticks==200){RunicShieldClient.add(mc.player,0,90);RunicShieldClient.add(mc.player,0,270);}if(ticks==202)LiquidDeathAudit.shot(mc,"runic-shield-hemisphere.png");if(ticks==250)LiquidDeathAudit.shot(mc,"runic-augmentation-active.png");if(ticks==1050)server.execute(()->finishAugment(server.getPlayerList().getPlayer(id)));if(ticks>=1065&&(ticks-1065)%15==0){check(augmentPassed,"augmentation complete");int index=(ticks-1065)/15;if(index>=9){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());String key=index<3?KEYS[0]:index<7?KEYS[index-2]:"RUNICAUGMENTATION";book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(key),index<3?index*2:index==8?2:0);mc.setScreen(book);}if(ticks>=1070&&(ticks-1070)%15==0)LiquidDeathAudit.shot(mc,"runic-book-"+(ticks-1070)/15+".png");}
}
